import { Agent, createWorkflowChain } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import * as dotenv from "dotenv";
import * as fs from "fs";
import * as path from "path";

dotenv.config();

async function main() {
  const writer = new Agent({
    name: "Writer",
    instructions: "You are a writer. Write a short article about the given topic.",
    model: openai("gpt-4o-mini"),
  });

  const editor = new Agent({
    name: "Editor",
    instructions: "You are an editor. Improve the grammar, clarity, and tone of the provided article.",
    model: openai("gpt-4o-mini"),
  });

  const workflow = createWorkflowChain({
    id: "writer-editor",
    name: "Writer-Editor Workflow",
    input: z.string(),
  })
    .andAgent(({ data }) => `Write a short article about: ${data}`, writer, {
      schema: z.object({ text: z.string() }),
    })
    .andAgent(({ data }) => `Improve this article:\n\n${data.text}`, editor, {
      schema: z.object({ text: z.string() }),
    });

  console.log("Running workflow...");
  const result = await workflow.run("The Future of AI");

  const outputPath = "/home/user/myproject/output.txt";
  if (result.result) {
    fs.writeFileSync(outputPath, result.result.text);
    console.log(`Output saved to ${outputPath}`);
  } else {
    console.error("Workflow failed to produce a result", result.error);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

