    .andAgent(async ({ data }) => `Improve this article:\n\n${data.text}`, editor, {
      schema: z.object({ text: z.string() }),
    });

  console.log("Running workflow...");
  const result = await workflow.run("The Future of AI");

  const outputPath = "/home/user/myproject/output.txt";
  if (result.status === "completed" && result.result) {
    fs.writeFileSync(outputPath, result.result.text);
    console.log(`Output saved to ${outputPath}`);
  } else {
    console.error("Workflow failed or was suspended", result.status, result.error);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
